"""Independent, deliberately naive reference implementation for testing."""
import json, re, sys

IDRE = re.compile(r'[A-Za-z0-9_.-]{1,32}')
HEXRE = re.compile(r'[0-9a-f]*')

def replay(req):
    caps = req['capacities']
    flows = {f['id']: f for f in req['flows']}
    for f in req['flows']:
        f['_path'] = list(f['path'])
        f['_tmpl'] = bytes.fromhex(f['template'])
        f['_labels'] = list(f['labels'])
        f['_kinds'] = f['kinds']
    tables = {}
    enabled = set()
    results = []
    def node_entries(n):
        return sum(1 for (nn, l) in tables if nn == n)
    for ev in req['events']:
        op = ev['op']
        if op == 'put':
            f = flows[ev['flow']]; node = ev['node']
            idx = f['_path'].index(node)
            label = f['_labels'][idx]
            key = (node, label)
            cur = tables.get(key)
            if cur == f['id']:
                results.append({'status':'ok'})
            elif any(g['id'] in enabled and node in g['_path']
                     and g['_labels'][g['_path'].index(node)] == label
                     for g in req['flows']):
                results.append({'status':'busy'})
            elif key not in tables and node_entries(node) >= caps[node]:
                results.append({'status':'full'})
            else:
                tables[key] = f['id']
                results.append({'status':'ok'})
        elif op == 'enable':
            f = flows[ev['flow']]
            if all(tables.get((n, f['_labels'][i])) == f['id']
                   for i, n in enumerate(f['_path'])):
                enabled.add(f['id']); results.append({'status':'ok'})
            else:
                results.append({'status':'unready'})
        elif op == 'disable':
            enabled.discard(ev['flow']); results.append({'status':'ok'})
        elif op == 'reset':
            enabled.clear(); results.append({'status':'ok'})
        elif op == 'packet':
            results.append(packet(flows[ev['flow']], bytes.fromhex(ev['header']),
                                  bytes.fromhex(ev['payload']), enabled))
    return {'results': results, 'active': sorted(enabled),
            'tables': sorted(({'node':n,'label':l,'flow':f} for (n,l),f in tables.items()),
                             key=lambda e:(e['node'],e['label']))}

def packet(f, hdr, payload, enabled):
    kinds = f['_kinds']; tmpl = f['_tmpl']; H = len(hdr)
    path = f['_path']; labels = f['_labels']; N = len(path); h = N-1
    if f['id'] not in enabled:
        mode, reason = 'ip','disabled'
    elif any(kinds[i]=='K' and hdr[i]!=tmpl[i] for i in range(H)):
        mode, reason = 'ip','mismatch'
    elif hdr[kinds.index('Q')] > 7:
        mode, reason = 'ip','qos'
    else:
        mode, reason = 'mpls','compressed'
    T = hdr[kinds.index('T')]
    # link i (0..h) carries ttl T-i; emitted iff T-i>=1 and i<=h
    wire = []
    for i in range(N):
        ttl = T - i
        if ttl <= 0: break
        if i > 0 and T - (i-1) <= 1: break
        if mode == 'ip':
            hh = bytearray(hdr); hh[kinds.index('T')] = ttl
            wire.append(bytes(hh).hex())
        else:
            res = bytes(hdr[i] for i in range(H) if kinds[i]=='D')
            q = hdr[kinds.index('Q')]
            word = (labels[i]<<12)|(q<<9)|(1<<8)|ttl
            wire.append(word.to_bytes(4,'big').hex()+res.hex()+payload.hex())
    delivered = None
    if len(wire) == N:
        if mode == 'ip':
            delivered = wire[-1]
        else:
            out = bytearray(H)
            res = bytes(hdr[i] for i in range(H) if kinds[i]=='D')
            k = 0
            for i in range(H):
                c = kinds[i]
                if c=='K': out[i]=tmpl[i]
                elif c=='D': out[i]=res[k]; k+=1
                elif c=='Z': out[i]=0
                elif c=='Q': out[i]=hdr[kinds.index('Q')]
                else: out[i]=T-h
            delivered = (bytes(out)+payload).hex()
    return {'mode':mode,'reason':reason,'wire':wire,'delivered':delivered,
            'byte_hops':sum(len(w)//2 for w in wire)}

def plan(req):
    caps = req['capacities']; flows = req['flows']
    warmup = req['warmup']; pinned = set(req['pinned']); offers = req['offers']
    ben = {}
    for f in flows:
        kinds = f['kinds']; H = len(bytes.fromhex(f['template']))
        nd = kinds.count('D'); N = len(f['path']); h = N-1
        per = (H-4-nd)*N
        tmpl = bytes.fromhex(f['template'])
        elig = 0; cum = 0
        for run in offers[f['id']]:
            hdr = bytes.fromhex(run['header'])
            good = all(kinds[i]!='K' or hdr[i]==tmpl[i] for i in range(H)) \
                   and hdr[kinds.index('Q')]<=7 and hdr[kinds.index('T')]>h
            if good:
                end = cum+run['count']
                if end > warmup:
                    elig += end - max(cum, warmup)
            cum += run['count']
        ben[f['id']] = per*elig
    # pinned feasibility
    for n in caps:
        c = sum(1 for f in flows if n in f['path'] and f['id'] in pinned)
        if c > caps[n]:
            return {'infeasible': True}
    best = None
    ids = [f['id'] for f in flows]
    for mask in range(1 << len(flows)):
        sel = {ids[i] for i in range(len(flows)) if mask >> i & 1}
        if not pinned <= sel: continue
        usage = {}
        ok = True
        for f in flows:
            if f['id'] in sel:
                for n in f['path']:
                    usage[n] = usage.get(n,0)+1
        for n,v in usage.items():
            if v > caps[n]: ok=False; break
        if not ok: continue
        b = sum(ben[i] for i in sel)
        score = (b, -len(sel))
        if best is None or score > best[0]:
            best = (score, sel)
    sel = best[1]
    return {'selected': sorted(sel), 'saved': sum(ben[i] for i in sel)}

def respond(line):
    req = json.loads(line)
    if req['mode'] == 'replay': return replay(req)
    return plan(req)

if __name__ == '__main__':
    for line in sys.stdin:
        sys.stdout.write(json.dumps(respond(line), separators=(',',':'))+'\n')
